 "content": "def transform(grid):
    """Connect consecutive markers in each row and column with color 3."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    marker = next((v for row in grid for v in row if v != 6), None)
    # The marker is the only non-background color in these tasks; determine
    # background as the most frequent value and marker as the other value.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next((v for v in counts if v != bg), marker)
    if marker is None:
        return out
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
